use crate::storage::Database;
use serde::{Serialize,Deserialize};
use serde_json::{json,Value};
use std::{collections::BTreeMap,fs::{self,OpenOptions},io::{Read,Write},os::windows::fs::{MetadataExt,OpenOptionsExt},path::PathBuf};
use rusqlite::params;
use windows_sys::Win32::Storage::FileSystem::ReplaceFileW;
#[derive(Clone,Serialize,Deserialize)]pub struct Options{pub shadows:u8,pub post_process:u8,pub effects:u8}
#[derive(Serialize,Deserialize)]struct Backup{bytes:Vec<u8>}
fn path()->Result<PathBuf,String>{let local=PathBuf::from(std::env::var_os("LOCALAPPDATA").ok_or("LOCALAPPDATA ausente")?);let mut current=local.canonicalize().map_err(|e|e.to_string())?;for part in ["FortniteGame","Saved","Config","WindowsClient","GameUserSettings.ini"]{current.push(part);let m=fs::symlink_metadata(&current).map_err(|e|e.to_string())?;if m.file_attributes()&0x400!=0{return Err("Reparse point na configuração; operação bloqueada".into())}}let m=fs::metadata(&current).map_err(|e|e.to_string())?;if !m.is_file()||m.len()>512_000||m.permissions().readonly(){return Err("Configuração demasiado grande, irregular ou só de leitura".into())}Ok(current)}
fn closed()->Result<(),String>{let system=sysinfo::System::new_all();if system.processes().values().any(|p|p.name().to_string_lossy().to_ascii_lowercase().starts_with("fortnite")){return Err("Feche completamente o Fortnite antes de analisar ou alterar a configuração".into())}Ok(())}
fn read()->Result<Vec<u8>,String>{closed()?;let p=path()?;let mut f=OpenOptions::new().read(true).share_mode(1).custom_flags(0x00200000).open(p).map_err(|e|e.to_string())?;let m=f.metadata().map_err(|e|e.to_string())?;if m.file_attributes()&0x400!=0||m.len()>512_000{return Err("Ficheiro não suportado".into())}let mut b=Vec::new();f.read_to_end(&mut b).map_err(|e|e.to_string())?;Ok(b)}
pub fn patch(original:&str,options:&Options)->Result<String,String>{
 if [options.shadows,options.post_process,options.effects].iter().any(|v|*v>3){return Err("A qualidade deve estar entre 0 e 3".into())}
 if original.contains('\0'){return Err("A configuração não é UTF-8 suportado".into())}
 let targets=BTreeMap::from([("sg.ShadowQuality",options.shadows),("sg.PostProcessQuality",options.post_process),("sg.EffectsQuality",options.effects)]);
 let mut found=BTreeMap::new();let mut section=false;let mut sections=0;let mut result=String::new();
 for segment in original.split_inclusive('\n'){
  let body=segment.trim_end_matches(['\r','\n']);let trimmed=body.trim().trim_start_matches('\u{feff}');
  if trimmed.starts_with('[')&&trimmed.ends_with(']'){section=trimmed=="[ScalabilityGroups]";if section{sections+=1;}}
  let mut changed=false;
  if section{if let Some((key,value))=trimmed.split_once('='){if let Some(new)=targets.get(key.trim()){if !["0","1","2","3"].contains(&value.trim()){return Err(format!("Valor atual não suportado: {key}"))}*found.entry(key.trim().to_string()).or_insert(0)+=1;let before=body.split_once('=').ok_or("Linha inválida")?.0;result.push_str(before);result.push('=');result.push_str(&new.to_string());result.push_str(&segment[body.len()..]);changed=true;}}}
  if !changed{result.push_str(segment);}
 }
 if sections!=1||targets.keys().any(|k|found.get(*k)!=Some(&1)){return Err("O ficheiro deve conter uma única secção ScalabilityGroups e uma ocorrência de cada opção suportada. Não são criadas opções em falta.".into())}Ok(result)
}
pub fn preview(options:Options)->Result<Value,String>{let bytes=read()?;let original=String::from_utf8(bytes).map_err(|_|"Codificação não suportada; ficheiro preservado")?;let proposed=patch(&original,&options)?;Ok(json!({"game":"Fortnite","path":path()?.to_string_lossy(),"original":original,"proposed":proposed,"options":options,"changed":original!=proposed,"compatibility":"Opções ScalabilityGroups existentes; o jogo pode substituí-las ao iniciar. Sem garantia de ganho."}))}
fn replace(expected:&[u8],new:&[u8])->Result<(),String>{
 closed()?;let p=path()?;let mut original=OpenOptions::new().read(true).share_mode(1|4).custom_flags(0x00200000).open(&p).map_err(|e|e.to_string())?;let mut current=Vec::new();original.read_to_end(&mut current).map_err(|e|e.to_string())?;if current!=expected{return Err("A configuração mudou desde a pré-visualização; nada foi sobrescrito".into())}
 let suffix=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos();let temporary=p.with_file_name(format!(".lucioz-{}-{suffix}.tmp",std::process::id()));
 let disk_backup=p.with_file_name(format!(".lucioz-original-{}-{suffix}.bak",std::process::id()));if disk_backup.exists(){return Err("Já existe uma cópia com este nome; operação bloqueada".into())}let result=(||{let mut f=OpenOptions::new().write(true).create_new(true).share_mode(0).open(&temporary).map_err(|e|e.to_string())?;f.write_all(new).map_err(|e|e.to_string())?;f.sync_all().map_err(|e|e.to_string())?;drop(f);closed()?;let wide=|p:&std::path::Path|p.as_os_str().to_string_lossy().encode_utf16().chain(Some(0)).collect::<Vec<_>>();let a=wide(&p);let b=wide(&temporary);let backup_name=wide(&disk_backup);let ok=unsafe{ReplaceFileW(a.as_ptr(),b.as_ptr(),backup_name.as_ptr(),0,std::ptr::null(),std::ptr::null())};if ok==0{return Err(format!("Falha de substituição: {}. Cópia de recuperação, quando criada: {}",std::io::Error::last_os_error(),disk_backup.display()))}drop(original);if read()?.as_slice()!=new{return Err("Não foi possível verificar o conteúdo substituído".into())}Ok(())})();let _=fs::remove_file(&temporary);result
}
pub fn apply(db:&Database,expected:String,options:Options)->Result<Value,String>{let current=read()?;if current!=expected.as_bytes(){return Err("Configuração alterada desde a análise".into())}let proposed=patch(&expected,&options)?;if proposed==expected{return Ok(json!({"status":"unchanged"}))}let previous=serde_json::to_string(&Backup{bytes:current}).map_err(|e|e.to_string())?;let new=serde_json::to_string(&Backup{bytes:proposed.as_bytes().to_vec()}).map_err(|e|e.to_string())?;let conn=db.0.lock().map_err(|e|e.to_string())?;conn.execute("INSERT INTO changes(optimization_id,previous_value,new_value,status,category) VALUES('game.fortnite.scalability',?1,?2,'pending','Jogos')",params![previous,new]).map_err(|e|e.to_string())?;let id=conn.last_insert_rowid();drop(conn);let result=replace(expected.as_bytes(),proposed.as_bytes());db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status=?1,error=?2 WHERE id=?3",params![if result.is_ok(){"applied"}else{"failed"},result.as_ref().err(),id]).map_err(|e|e.to_string())?;db.log("game.settings",&json!({"id":id,"success":result.is_ok()}).to_string())?;result?;Ok(json!({"id":id,"verified":true}))}
pub fn restore(db:&Database,id:i64)->Result<Value,String>{let conn=db.0.lock().map_err(|e|e.to_string())?;let(old,new,status):(String,String,String)=conn.query_row("SELECT previous_value,new_value,status FROM changes WHERE id=?1 AND optimization_id='game.fortnite.scalability'",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|e|e.to_string())?;let newer:i64=conn.query_row("SELECT COUNT(*) FROM changes WHERE optimization_id='game.fortnite.scalability' AND id>?1 AND status!='restored'",[id],|r|r.get(0)).map_err(|e|e.to_string())?;drop(conn);if status=="restored"{return Ok(json!({"status":"restored"}))}if newer>0{return Err("Restaure primeiro a alteração mais recente deste jogo".into())}let old:Backup=serde_json::from_str(&old).map_err(|e|e.to_string())?;let new:Backup=serde_json::from_str(&new).map_err(|e|e.to_string())?;let current=read()?;if current!=old.bytes{replace(&new.bytes,&old.bytes)?;}db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status='restored',error=NULL WHERE id=?1",[id]).map_err(|e|e.to_string())?;db.log("game.restore",&id.to_string())?;Ok(json!({"status":"restored","verified":true}))}
#[cfg(test)]mod tests{use super::*;#[test]fn preserves_unrelated_content_and_line_endings(){let old="; comment\r\n[ScalabilityGroups]\r\nsg.ShadowQuality=3\r\nsg.PostProcessQuality=2\r\nsg.EffectsQuality=1\r\nsg.TextureQuality=3\r\n[Other]\r\nKey=Value\r\n";let new=patch(old,&Options{shadows:0,post_process:1,effects:2}).unwrap();assert!(new.contains("sg.TextureQuality=3\r\n"));assert!(new.contains("[Other]\r\nKey=Value\r\n"));assert!(new.contains("sg.ShadowQuality=0\r\n"));}#[test]fn rejects_ambiguous_or_unsupported_config(){assert!(patch("[ScalabilityGroups]\nsg.ShadowQuality=4\n",&Options{shadows:0,post_process:0,effects:0}).is_err());assert!(patch("",&Options{shadows:9,post_process:0,effects:0}).is_err());}}
